<?php
/** @var array<int, array<string, mixed>> $teams */
$teams = $teams ?? [];
$track = (int) ($track ?? 1);
$labels = $labels ?? [];
$text = static fn (string $key, string $fallback): string => (string) ($labels[$key] ?? $fallback);
$replace = static fn (string $value, int $team): string => str_replace('{team}', (string) $team, $value);
ob_start();
?>
<section class="panel" data-page="race" data-track="<?= $track ?>" data-endpoint="/robo/api/tracks/<?= $track ?>">
  <div class="data-table-wrap"><table class="data-table"><thead><tr><th rowspan="2"><?= htmlspecialchars($text('team', 'Tým'), ENT_QUOTES, 'UTF-8') ?></th><th colspan="7"><?= htmlspecialchars($text('checkpoints', 'Průjezdní body'), ENT_QUOTES, 'UTF-8') ?></th><th colspan="5"><?= htmlspecialchars($text('laps', 'Časy kompletních kol (ms)'), ENT_QUOTES, 'UTF-8') ?></th><th rowspan="2"><?= htmlspecialchars($text('did_not_stop', 'Nezastavení'), ENT_QUOTES, 'UTF-8') ?></th><th rowspan="2"><?= htmlspecialchars($text('confirmed', 'Potvrzeno'), ENT_QUOTES, 'UTF-8') ?></th></tr><tr><?php foreach (['1','2','3','4','5','6',$text('finish', 'Cíl')] as $point): ?><th><?= htmlspecialchars($point, ENT_QUOTES, 'UTF-8') ?></th><?php endforeach; ?><?php for ($i=1;$i<=5;$i++): ?><th><?= htmlspecialchars($text('time_'.$i, 'Čas '.$i), ENT_QUOTES, 'UTF-8') ?></th><?php endfor; ?></tr></thead>
  <tbody><?php foreach ($teams as $team): $id=(int)$team['id']; ?><tr data-team-id="<?= $id ?>" class="<?= !empty($team['confirmed']) ? 'row-complete' : '' ?>"><td><button class="team-button" type="button" data-help-modal="race-team-<?= $id ?>"><?= (int)$team['number'] ?></button><dialog id="race-team-<?= $id ?>"><div class="modal-header"><h2><?= htmlspecialchars($replace($text('team_title', 'Tým {team}'), (int) $team['number']), ENT_QUOTES, 'UTF-8') ?></h2><button class="modal-close" type="button" data-close-modal>×</button></div><div class="modal-body team-details"><p><?= htmlspecialchars($text('school', 'Škola'), ENT_QUOTES, 'UTF-8') ?>: <?= htmlspecialchars((string)($team['school'] ?? ''),ENT_QUOTES,'UTF-8') ?></p><p><?= htmlspecialchars($text('contestants', 'Soutěžící'), ENT_QUOTES, 'UTF-8') ?>: <?= htmlspecialchars((string)($team['members'] ?? ''),ENT_QUOTES,'UTF-8') ?></p></div></dialog></td>
    <?php foreach (['checkpoint_1','checkpoint_2','checkpoint_3','checkpoint_4','checkpoint_5','checkpoint_6','finish'] as $field): $count=(int)($team[$field]??0); $missing=$count===0; ?><td><button class="team-button<?= $missing ? ' value-missing' : '' ?>" type="button" data-long-press="edit-<?= $id ?>-<?= $field ?>" data-field="<?= $field ?>" data-value="<?= $count ?>" data-empty-value="?"><?= $missing ? (!empty($team['confirmed']) ? '' : '?') : $count.'x' ?></button><dialog id="edit-<?= $id ?>-<?= $field ?>"><div class="modal-header"><h2><?= htmlspecialchars($text('edit_value', 'Upravit hodnotu'), ENT_QUOTES, 'UTF-8') ?></h2><button class="modal-close" type="button" data-close-modal>×</button></div><div class="modal-body"><label class="form-field"><?= htmlspecialchars($text('pass_count', 'Počet průjezdů'), ENT_QUOTES, 'UTF-8') ?><input type="number" min="0" max="99" value="<?= $count ?>" data-field="<?= $field ?>"></label></div><div class="modal-footer"><button class="button button-save" type="button" data-save-field="<?= $id ?>"><?= htmlspecialchars($text('save', 'Uložit'), ENT_QUOTES, 'UTF-8') ?></button></div></dialog></td><?php endforeach; ?>
    <?php for ($i=1;$i<=5;$i++): $field='time_'.$i; $value=$team[$field] ?? null; $missing=$value===null||$value===''; ?><td class="<?= !empty($team['best_time']) && (int)$value === (int)$team['best_time'] ? 'best-time' : '' ?>"><button class="team-button<?= $missing ? ' value-missing' : '' ?>" type="button" data-open-modal="edit-<?= $id ?>-<?= $field ?>" data-field="<?= $field ?>" data-empty-value="?"><?= $missing ? (!empty($team['confirmed']) ? '' : '?') : (int)$value ?></button><dialog id="edit-<?= $id ?>-<?= $field ?>"><div class="modal-header"><h2><?= htmlspecialchars($text($field, 'Čas '.$i), ENT_QUOTES, 'UTF-8') ?></h2><button class="modal-close" type="button" data-close-modal>×</button></div><div class="modal-body"><label class="form-field"><?= htmlspecialchars($text('time_milliseconds', 'Čas v milisekundách'), ENT_QUOTES, 'UTF-8') ?><input type="number" min="1" max="300000" value="<?= htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8') ?>" data-field="<?= $field ?>"></label></div><div class="modal-footer"><button class="button button-save" type="button" data-save-field="<?= $id ?>"><?= htmlspecialchars($text('save', 'Uložit'), ENT_QUOTES, 'UTF-8') ?></button></div></dialog></td><?php endfor; ?>
    <td><button type="button" class="check-action" data-field="did_not_stop" aria-pressed="<?= !empty($team['did_not_stop']) ? 'true' : 'false' ?>"><?= !empty($team['did_not_stop']) ? '✓' : '' ?></button></td><td><button type="button" class="completion" data-field="confirmed" data-state="<?= !empty($team['confirmed']) ? (!empty($team['best_time']) ? 'confirmed' : 'invalid') : 'pending' ?>" aria-label="<?= htmlspecialchars(!empty($team['confirmed']) ? (!empty($team['best_time']) ? $text('result_confirmed', 'Výsledek potvrzen') : $text('result_invalid', 'Potvrzeno bez platného času')) : $text('result_pending', 'Rozpracovaný výsledek'), ENT_QUOTES, 'UTF-8') ?>"><?= !empty($team['confirmed']) ? (!empty($team['best_time']) ? '✓' : '×') : '?' ?></button></td></tr><?php endforeach; ?></tbody></table></div>
</section>
<?php $content=ob_get_clean(); $help='<p>' . htmlspecialchars($text('help', 'Krátký stisk průjezdního bodu hodnotu zvýší. Podržením otevřete přesnou úpravu. Zadejte nejvýše pět časů kompletních kol. Nejnižší platný čas se zvýrazní zeleně. Potvrzení bez platného času se označí červeným křížkem.'), ENT_QUOTES, 'UTF-8') . '</p>'; require __DIR__.'/app-shell-v042.php';
